Clase Contador
  Privado Definir valor Como Entero;

  Metodo Constructor(inicial Como Entero)
    Este.valor <- inicial;
  FinMetodo

  Metodo Sumar()
    Este.valor <- Este.valor + 1;
  FinMetodo

  Metodo Actual() Como Entero
    Retornar Este.valor;
  FinMetodo
FinClase

Algoritmo Pasos
  Definir pasos Como Contador <- Nuevo Contador(10);
  pasos.Sumar();
  pasos.Sumar();
  Escribir pasos.Actual();
FinAlgoritmo
